#[derive(Clone, Copy, Debug, PartialEq)]
pub enum GAnimationCurve {
    Spring { response: f32, damping: f32 },
    EaseInOut { duration: f32 },
    EaseOut { duration: f32 },
    Linear { duration: f32 },
}

pub mod animations {
    use super::GAnimationCurve;

    pub const BOUNCY: GAnimationCurve = GAnimationCurve::Spring { response: 0.4, damping: 0.7 };
    pub const SMOOTH: GAnimationCurve = GAnimationCurve::EaseInOut { duration: 0.25 };
    pub const QUICK: GAnimationCurve = GAnimationCurve::EaseOut { duration: 0.15 };
    pub const PANE: GAnimationCurve = GAnimationCurve::Spring { response: 0.38, damping: 0.9 };
    pub const LINEAR: GAnimationCurve = GAnimationCurve::Linear { duration: 0.1 };
    pub const PAGE: GAnimationCurve = GAnimationCurve::Spring { response: 0.24, damping: 0.9 };
    pub const GROUND: GAnimationCurve = GAnimationCurve::EaseInOut { duration: 0.45 };
    pub const SHARED: GAnimationCurve = GAnimationCurve::Spring { response: 0.42, damping: 0.86 };
    /// How far a page rises as it comes in, in points.
    pub const PAGE_RISE: f32 = 8.0;
}

/// The font families.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum GFamily {
    Text,
    Display,
    Mono,
}

impl GFamily {
    pub const fn name(self) -> &'static str {
        match self {
            GFamily::Text => "IBM Plex Sans",
            GFamily::Display => "IBM Plex Sans Condensed",
            GFamily::Mono => "IBM Plex Mono",
        }
    }
}

/// IBM Plex's files (SIL Open Font License), embedded: `fonts::register` hands them to GPUI.
